// The complete lifecycle in 4 steps:

// 1. Initial State
let state = { count: 0 };

// 2. User clicks a button in the UI, creating an ACTION
const action = { type: 'INCREMENT' };

// 3. The REDUCER receives the current state and the action
function reducer(state, action) {
  if (action.type === 'INCREMENT') return { count: state.count + 1 };
  return state;
}

// 4. The STORE updates the state, and the UI re-renders with { count: 1 }
state = reducer(state, action);
